import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const fmt=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(Math.round(n));
const num=n=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Math.round(n));
const TYPES=[
{id:'olive',name:'Zeytinyağı fabrikası',icon:'🫒',desc:'Ege zeytinini katma değerli soğuk sıkım yağa dönüştür.',cost:72000,value:84000,daily:9300,expense:5100,product:'Zeytinyağı',capacity:8,area:'Sanayi bölgesi'},
{id:'farm',name:'Tarım işletmesi',icon:'🌾',desc:'Verimli topraklarda buğday, pamuk ve zeytin yetiştir.',cost:46000,value:53000,daily:6200,expense:3300,product:'Buğday',capacity:12,area:'Bereketli ova'},
{id:'market',name:'Market zinciri',icon:'🛒',desc:'Mahallelerden başlayıp şehrin her köşesine ulaş.',cost:56000,value:65000,daily:7200,expense:4400,product:'Gıda sepeti',capacity:9,area:'Şehir merkezi'},
{id:'logistics',name:'Lojistik şirketi',icon:'🚚',desc:'Tedarikçileri, fabrikaları ve müşterileri birbirine bağla.',cost:68000,value:79000,daily:9100,expense:5700,product:'Nakliye hizmeti',capacity:10,area:'Lojistik koridoru'},
{id:'auto',name:'Otomotiv fabrikası',icon:'🚗',desc:'Yerli üretimle geleceğin ulaşım araçlarını tasarla.',cost:180000,value:215000,daily:24000,expense:16800,product:'Otomobil',capacity:2,area:'Organize sanayi'},
{id:'build',name:'İnşaat şirketi',icon:'🏗️',desc:'Yeni konutlar ve iş merkezleriyle şehrin siluetini değiştir.',cost:125000,value:148000,daily:16800,expense:10700,product:'Konut projesi',capacity:3,area:'Yeni gelişim bölgesi'},
{id:'tech',name:'Teknoloji şirketi',icon:'💡',desc:'Yazılım ve akıllı çözümler geliştir, dijital geleceğe yatırım yap.',cost:145000,value:172000,daily:19500,expense:11800,product:'Yazılım lisansı',capacity:6,area:'Teknopark'}
];
const PRODUCTS=[{name:'Zeytinyağı',price:380,base:380,stock:30,icon:'🫒',supply:1},{name:'Buğday',price:24,base:24,stock:90,icon:'🌾',supply:1},{name:'Gıda sepeti',price:210,base:210,stock:55,icon:'🧺',supply:1},{name:'Nakliye hizmeti',price:520,base:520,stock:24,icon:'🚚',supply:1},{name:'Otomobil',price:685000,base:685000,stock:8,icon:'🚗',supply:1},{name:'Konut projesi',price:1250000,base:1250000,stock:6,supply:1,icon:'🏗️'},{name:'Yazılım lisansı',price:4800,base:4800,stock:20,supply:1},{name:'Pamuk',price:68,base:68,stock:40,supply:1,icon:'☁️'}];
const EVENTS=[{title:'Bereketli hasat',text:'Bölgede yağışlar ideal seyretti. Tarım ürünlerinde arz arttı, buğday fiyatı geriledi.',effect:'Tarım arzı +',kind:'harvest'},{title:'Turizm sezonu açıldı',text:'Ege kıyılarına ziyaretçi akını başladı. Gıda ve lojistik talebi yükseliyor.',effect:'Talep artışı',kind:'tourism'},{title:'Enerji maliyetleri arttı',text:'Enerji piyasalarındaki hareketlilik üretim giderlerini yükseltti.',effect:'Gider baskısı',kind:'energy'},{title:'Dijital dönüşüm teşviki',text:'Yeni teşvik programı teknoloji yatırımlarını ve yazılım talebini destekliyor.',effect:'Teknoloji fırsatı',kind:'tech'},{title:'İhracat anlaşması',text:'Bölge limanından yeni ticaret hattı açıldı. Yerli üretim dış pazara ulaşıyor.',effect:'Üreticiye fırsat',kind:'export'},{title:'Pazar sakin',text:'Ekonomik göstergeler dengeli. Piyasa olağan seyrinde ilerliyor.',effect:'Dengeli görünüm',kind:'calm'}];
const COMPETITOR_SEEDS=[{name:'Marmara Yatırım',sector:'Sanayi & otomotiv',icon:'🏭',value:420000},{name:'Ege Tarım Grubu',sector:'Tarım & gıda',icon:'🌿',value:275000},{name:'Ufuk Teknoloji',sector:'Teknoloji',icon:'🧠',value:350000}];
const defaultState=()=>({cash:100000,bank:0,debt:0,day:1,season:0,companies:[],inventory:{},land:1,event:5,eventLog:[],history:[100000],transactions:[{day:1,text:'Kurucu sermayesi',amount:100000}],missionsDone:[],achievements:[],tutorial:0,marketMood:0,competitors:COMPETITOR_SEEDS.map(x=>({...x})),rep:0});
let state;try{state=JSON.parse(localStorage.getItem('anadolu-holding-save'))||defaultState()}catch{state=defaultState()}
let lastPrices=PRODUCTS.map(p=>p.price),modalResolver=null;
const save=()=>localStorage.setItem('anadolu-holding-save',JSON.stringify(state));
function transact(text,amount){state.transactions.unshift({day:state.day,text,amount});state.transactions=state.transactions.slice(0,12);if(amount<0)state.cash+=amount;else state.cash+=amount;save();render()}
function notify(msg,error=false){const t=document.getElementById('toast');t.innerHTML=msg;t.classList.toggle('error',error);t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),2800)}
function ask(title,body,ok='Onayla',cancel='Vazgeç'){return new Promise(resolve=>{modalResolver=resolve;document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;document.getElementById('modalActions').innerHTML=`<button class="btn secondary" data-choice="false">${cancel}</button><button class="btn" data-choice="true">${ok}</button>`;document.getElementById('modal').classList.add('show')})}
document.getElementById('modalActions').onclick=e=>{const b=e.target.closest('[data-choice]');if(!b)return;document.getElementById('modal').classList.remove('show');modalResolver?.(b.dataset.choice==='true');};
function go(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${view}`));document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.getElementById('crumb').textContent=({city:'Şehir görünümü',dashboard:'Genel bakış',companies:'Şirketlerim',market:'Pazar yeri',bank:'Banka & finans',goals:'Görevler'})[view];if(view==='city')resizeWorld();if(view==='dashboard')drawChart()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));
document.getElementById('saveBtn').onclick=()=>{save();notify('Oyun ilerlemen kaydedildi. <b>✓</b>')};
document.getElementById('resetBtn').onclick=async()=>{if(await ask('Yeni oyun başlatılsın mı?','Mevcut ilerlemen bu cihazdan silinir. Bu işlem geri alınamaz.','Yeni oyun başlat')){localStorage.removeItem('anadolu-holding-save');state=defaultState();render();go('city');showTutorial(0);notify('Yeni girişimin hayırlı olsun!')}};
document.getElementById('newCompany').onclick=()=>go('companies');
document.getElementById('dashDay').onclick=()=>advanceDay();
document.getElementById('nextDay').onclick=()=>advanceDay();
const owned=id=>state.companies.some(c=>c.id===id);
const wealth=()=>state.cash+state.bank-state.debt+state.companies.reduce((a,c)=>a+c.value,0)+Object.values(state.inventory).reduce((a,v)=>a+v,0);
const totals=()=>state.companies.reduce((a,c)=>({income:a.income+c.daily,expense:a.expense+c.expense}),{income:0,expense:0});

