const totals=()=>state.companies.reduce((a,c)=>({income:a.income+c.daily,expense:a.expense+c.expense}),{income:a.income??0,expense:a.expense??0});
function buyCompany(id){const t=TYPES.find(x=>x.id===id);if(!t||owned(id))return;const cost=Math.round(t.cost*(state.land===1?1:1+(state.land-1)*.06));if(state.cash<cost){notify(`Միջոցները բավարար չեն. Պետք է ${fmt(cost)}։`,true);return}state.cash-=cost;state.companies.push({...t,value:t.value,level:1,days:0});state.transactions.unshift({day:state.day,text:`${t.name} kuruldu`,amount:-cost});state.rep+=10;save();render();notify(`<b>${t.name}</b> şehrin ekonomisine katıldı!`);if(state.companies.length===1)finishTutorialStep(1)}
function upgradeCompany(id){const c=state.companies.find(x=>x.id===id);if(!c)return;const cost=Math.round(c.cost*(.38+c.level*.12));if(state.cash<cost){notify(`Genişleme için ${fmt(cost)} gerekiyor.`,true);return}state.cash-=cost;c.level++;c.value=Math.round(c.value*1.35);c.daily=Math.round(c.daily*1.35);c.expense=Math.round(c.expense*1.2);c.capacity=Math.ceil(c.capacity*1.25);state.transactions.unshift({day:state.day,text:`${c.name} genişletildi`,amount:-cost});state.rep+=5;save();render();notify(`<b>${c.name}</b> kapasitesi büyütüldü.`)}
function advanceDay(){state.day++;let t=totals(),mult=state.event===2?1.12:1;let income=0,expense=0;state.companies.forEach(c=>{const competition=state.competitors.some(r=>r.sector.includes(c.id==='tech'?'Teknoloji':c.id==='farm'?'Tarım':'') )?.94:1;const sales=Math.round(c.daily*mult*competition*(.93+Math.random()*.16));const costs=Math.round(c.expense*(state.event===2?1.2:state.event===1?.96:1));income+=sales;expense+=costs;c.days++;const prod=PRODUCTS.find(p=>p.name===c.product);if(prod){const quantity=Math.max(1,Math.floor(c.capacity*(.8+Math.random()*.3)));const marketQty=Math.min(quantity,Math.max(0,prod.stock+5));if(marketQty){const added=marketQty*prod.price;income+=Math.round(added*.08);prod.stock=Math.max(2,prod.stock-marketQty*.12)}}});const taxes=Math.round(income*.05);expense+=taxes;let interest=Math.round(state.debt*.0035);expense+=interest;state.cash+=income-expense;state.bank=Math.round(state.bank*1.0003);state.history.push(state.cash);state.history=state.history.slice(-7);state.competitors.forEach(c=>{c.value=Math.round(c.value*(.985+Math.random()*.035))});updateMarket();state.event=Math.floor(Math.random()*EVENTS.length);const ev=EVENTS[state.event];state.eventLog.unshift({day:state.day,...ev});state.eventLog=state.eventLog.slice(0,5);state.transactions.unshift({day:state.day,text:'Günlük faaliyet ve vergiler',amount:income-expense});state.transactions=state.transactions.slice(0,12);const month=['İlkbahar','Yaz','Sonbahar','Kış'][Math.floor((state.day-1)/30)%4];if(state.day%30===0)state.season++;save();render();notify(`Gün ${state.day}: net ${income-expense>=0?'kazanç':'zarar'} <b>${fmt(income-expense)}</b>`);checkAchievements();checkMissions()}
function updateMarket(){PRODUCTS.forEach((p,i)=>{const prev=p.price;let drift=(Math.random()-.48)*.055;const own=state.companies.find(c=>c.product===p.name);if(own)drift-=.009;if(state.event===0&&p.name==='Buğday')drift-=.12;if(state.event===1&&['Gıda sepeti','Nakliye hizmeti'].includes(p.name))drift+=.085;if(state.event===2)drift+=.025;if(state.event===3&&p.name==='Yazılım lisansı')drift+=.16;if(state.event===4&&['Zeytinyağı','Otomobil','Yazılım lisansı'].includes(p.name))drift+=.1;p.price=Math.max(Math.round(p.base*.65),Math.round(Math.min(p.base*1.7,prev*(1+drift))));p.stock=Math.max(4,Math.min(120,p.stock+Math.round((Math.random()-.5)*8)));});state.marketMood=(state.marketMood+1)%5}
function buyProduct(name,qty=1){const p=PRODUCTS.find(x=>x.name===name);if(!p)return;const cost=p.price*qty;if(state.cash<cost){notify('Bu alışveriş için nakdin yetersiz.',true);return}const held=state.inventory[name]||0;if(Object.values(state.inventory).reduce((a,b)=>a+b,0)+qty>50+(state.land-1)*25){notify('Depo kapasitesi dolu. Yeni arazi alarak depoyu büyüt.',true);return}state.cash-=cost;state.inventory[name]=held+qty;state.transactions.unshift({day:state.day,text:`${name} satın alındı (${qty} adet)`,amount:-cost});save();render();notify(`${qty} adet <b>${name}</b> depoya eklendi.`)}
function sellProduct(name,qty=1){const p=PRODUCTS.find(x=>x.name===name),held=state.inventory[name]||0;qty=Math.min(qty,held);if(!p||qty<=0){notify('Depoda satılacak ürün yok.',true);return}const proceeds=Math.round(p.price*qty*(1+(owned('market')?.08:0)));state.cash+=proceeds;state.inventory[name]-=qty;if(!state.inventory[name])delete state.inventory[name];state.transactions.unshift({day:state.day,text:`${name} satıldı (${qty} adet)`,amount:proceeds});state.rep+=1;save();render();notify(`Satış tamamlandı: <b>${fmt(proceeds)}</b>`);checkMissions()}
function deposit(){const amount=Math.min(10000,state.cash);if(amount<1000){notify('Bankaya yatırmak için en az ₺1.000 nakit gerekir.',true);return}state.cash-=amount;state.bank+=amount;state.transactions.unshift({day:state.day,text:'Vadeli hesaba yatırıldı',amount:-amount});save();render();notify(`${fmt(amount)} banka hesabına aktarıldı.`)}
function withdraw(){const amount=Math.min(10000,state.bank);if(amount<=0){notify('Bankada kullanılabilir bakiye yok.',true);return}state.bank-=amount;state.cash+=amount;state.transactions.unshift({day:state.day,text:'Banka hesabından çekildi',amount});save();render();notify(`${fmt(amount)} nakde aktarıldı.`)}
async function takeLoan(){const cap=Math.max(0,Math.round((state.companies.reduce((a,c)=>a+c.value,0)+40000)*.6-state.debt));if(cap<10000){notify('Kredi için önce şirket değerini artırmalısın.',true);return}const input=prompt(`Kredi tutarı (en fazla ${fmt(cap)}). Günlük faiz %0,35.`,'50000');if(input===null)return;const amount=Math.floor(Number(input));if(!Number.isFinite(amount)||amount<10000||amount>cap){notify('Tutar 10.000 TL ile kredi limitin arasında olmalı.',true);return}state.cash+=amount;state.debt+=amount;state.transactions.unshift({day:state.day,text:'İşletme kredisi kullanıldı',amount});save();render();notify(`${fmt(amount)} işletme kredisi hesabına geçti.`)}
async function repayLoan(){const amount=Math.min(state.debt,state.cash,Math.max(1000,Number(prompt(`Kredi borcun ${fmt(state.debt)}. Ödeme tutarı?`,String(Math.min(state.debt,10000)))||0));if(amount<=0)return;state.cash-=amount;state.debt-=amount;state.transactions.unshift({day:state.day,text:'Kredi anapara ödemesi',amount:-amount});save();render();notify(`${fmt(amount)} kredi anaparası ödendi.`)}
