const LANDS=[{id:1,name:'Küçük depo',area:'Şehir merkezi',cost:0,icon:'📦',owned:true},{id:2,name:'Verimli ova',area:'Tarım arazisi',cost:65000,icon:'🌱'},{id:3,name:'Sanayi arsası',area:'Organize sanayi',cost:145000,icon:'🏭'},{id:4,name:'Liman lojistik sahası',area:'Ege kıyısı',cost:280000,icon:'⚓'}];
const MISSIONS=[{id:'first',title:'İlk yatırımını yap',desc:'Bir iş kolunda şirket kur.',reward:8000,check:()=>state.companies.length>=1},{id:'sale',title:'İlk ticaretini tamamla',desc:'Pazardan bir ürün sat.',reward:4500,check:()=>state.rep>=1},{id:'profit',title:'Bir günlük kâr',desc:'Bir günde pozitif net kazanç elde et.',reward:7000,check:()=>state.history.length>1&&state.history.at(-1)>state.history.at(-2)},{id:'empire',title:'Büyüyen holding',desc:'Üç farklı şirket kur.',reward:25000,check:()=>state.companies.length>=3}];
const BADGES=[{id:'founder',icon:'🌱',title:'Girişimci ruh',desc:'İlk şirketini kur.',check:()=>state.companies.length>=1},{id:'trader',icon:'🤝',title:'Ticaret ustası',desc:'Pazarda satış yap.',check:()=>state.rep>=1},{id:'employer',icon:'👥',title:'İstihdam lideri',desc:'Üç şirkete ulaş.',check:()=>state.companies.length>=3},{id:'wealth',icon:'💎',title:'İlk milyon',desc:'Toplam varlığını ₺1.000.000 üzerine çıkar.',check:()=>wealth()>=1000000},{id:'landlord',icon:'🏡',title:'Toprak sahibi',desc:'İlk ek arazini satın al.',check:()=>state.land>1}];
function metric(label,value,sub,icon,down=false){return `<div class="metric"><div class="label"><span>${label}</span><span>${icon}</span></div><strong>${value}</strong><small class="${down?'down':''}">${sub}</small></div>`}
function render(){document.getElementById('dateLabel').textContent=`${state.day}. Gün · ${['İlkbahar','Yaz','Sonbahar','Kış'][Math.floor((state.day-1)/30)%4]}`;renderMetrics();renderCompanies();renderMarket();renderBank();renderGoals();renderEvent();drawChart();if(worldReady)syncWorld();save()}
function renderMetrics(){const t=totals(),net=t.income-t.expense;document.getElementById('metrics').innerHTML=metric('Toplam varlık',fmt(wealth()),`${state.companies.length} şirket · ${state.land} arazi`,'◈')+metric('Kullanılabilir nakit',fmt(state.cash),`Banka: ${fmt(state.bank)}`,'₺')+metric('Günlük gelir',fmt(t.income),state.companies.length?'Şirket faaliyetleri':'Henüz faaliyette şirket yok','↗')+metric('Net günlük kâr',fmt(net),`Giderler ${fmt(t.expense)}`,net>=0?'✦':'↘',net<0);
document.getElementById('portfolioCount').textContent=`${state.companies.length} şirket`;document.getElementById('portfolio').innerHTML=state.companies.length?state.companies.map(c=>`<div class="company-row"><div class="company-left"><div class="company-icon">${c.icon}</div><div><b>${c.name}</b><small>${c.area} · Seviye ${c.level}</small></div></div><span class="status">Faaliyette</span></div>`).join(''):'<div class="empty">İlk şirketini kurarak portföyünü oluşturmaya başla.</div>';
document.getElementById('dashboardPrices').innerHTML=PRODUCTS.slice(0,4).map(p=>`<div class="price-row"><div>${p.icon||'📦'} &nbsp;${p.name}<small>Stok: ${num(p.stock)} birim</small></div><b>${fmt(p.price)}</b></div>`).join('')}
function renderCompanies(){document.getElementById('companyGrid').innerHTML=state.companies.length?state.companies.map(c=>{const cost=Math.round(c.cost*(.38+c.level*.12));return `<article class="card biz-card"><div class="biz-top"><div class="biz-emblem">${c.icon}</div><span class="status">● Faaliyette</span></div><h3>${c.name}</h3><p>${c.desc}</p><div class="biz-stats"><span>Günlük gelir<b>${fmt(c.daily)}</b></span><span>Şirket değeri<b>${fmt(c.value)}</b></span></div><div class="biz-actions"><button class="btn" onclick="window.upgrade('${c.id}')">↑ Genişlet · ${fmt(cost)}</button><button class="btn secondary" onclick="window.inspect('${c.id}')">Detay</button></div></article>`}).join(''):'<div class="card empty" style="grid-column:1/-1">Henüz şirketin yok. 100.000 TL sermayenle zeytinyağı fabrikası veya tarım işletmesi kurabilirsin.</div>';
document.getElementById('opportunityGrid').innerHTML=TYPES.filter(t=>!owned(t.id)).map(t=>`<article class="card biz-card"><div class="biz-top"><div class="biz-emblem">${t.icon}</div><span class="status locked">Yatırım fırsatı</span></div><h3>${t.name}</h3><p>${t.desc}</p><div class="biz-stats"><span>Kuruluş maliyeti<b>${fmt(t.cost)}</b></span><span>Günlük net tahmin<b class="positive">${fmt(t.daily-t.expense)}</b></span></div><button class="btn" style="width:100%" onclick="window.buy('${t.id}')">＋ Şirket kur · ${fmt(t.cost)}</button></article>`).join('')||'<div class="card empty" style="grid-column:1/-1">Tüm sektörlerde yerini aldın. Harika!</div>'}
function renderMarket(){document.getElementById('marketTable').innerHTML=PRODUCTS.map((p,i)=>{const change=lastPrices[i]?Math.round((p.price-lastPrices[i])/lastPrices[i]*100):0;return `<tr><td>${p.icon||'📦'} ${p.name}</td><td><b>${fmt(p.price)}</b></td><td class="${change>=0?'positive':'negative'}">${change>=0?'↗ +':'↘ '}${change}%</td><td><div class="product-controls"><button class="tiny-btn" onclick="window.buyProduct('${p.name}')">Al</button><button class="tiny-btn" onclick="window.sellProduct('${p.name}')">Sat</button></div></td></tr>`}).join('');
document.getElementById('warehouseCapacity').textContent=`Kapasite: ${50+(state.land-1)*25} birim`;const stock=Object.entries(state.inventory);document.getElementById('inventory').innerHTML=stock.length?stock.map(([name,qty])=>{const p=PRODUCTS.find(x=>x.name===name);return `<div class="price-row" style="padding:12px 0;border-bottom:1px solid var(--line)"><div>${p?.icon||'📦'} &nbsp;${name}<small>${num(qty)} birim · ${fmt(p?.price*qty||0)} değer</small></div><div><b>${num(qty)}</b> <button class="tiny-btn" onclick="window.sellProduct('${name}',${qty})">Sat</button></div></div>`}).join(''):'<div class="empty">Depon boş. Pazardan alım yap veya üretim şirketi kur.</div>';
document.getElementById('marketEvent').innerHTML=`<div style="font-size:22px">${state.event===0?'🌧️':state.event===1?'☀️':state.event===2?'⚡':state.event===3?'💻':state.event===4?'🚢':'📊'}</div><div><strong>${EVENTS[state.event].title}</strong><span>${EVENTS[state.event].text}</span></div>`;document.getElementById('marketLog').innerHTML=state.eventLog.length?state.eventLog.map(e=>`<div class="price-row" style="padding:9px 0;border-bottom:1px solid var(--line)"><span><b>Gün ${e.day} · ${e.title}</b><small>${e.text}</small></span><span class="status">${e.effect}</span></div>`).join(''):'<div class="empty">Günlük ekonomik gelişmeler burada gösterilecek.</div>'}

