function renderEvent(){document.getElementById('eventDay').textContent=`Gün ${state.day}`;document.getElementById('eventPanel').innerHTML=`<div class="event-banner" style="margin:14px 0 0"><div style="font-size:19px">${state.event===0?'🌧️':state.event===1?'☀️':state.event===2?'⚡':state.event===3?'💻':state.event===4?'🚢':'📊'}</div><div><strong>${EVENTS[state.event].title}</strong><span>${EVENTS[state.event].text}</span></div></div>`}
function checkAchievements(){let changed=false;BADGES.forEach(b=>{if(!state.achievements.includes(b.id)&&b.check()){state.achievements.push(b.id);changed=true;notify(`Başarım açıldı: <b>${b.title}</b> 🏆`)}});if(changed){save();renderGoals()}}
function checkMissions(){MISSIONS.forEach(m=>{if(!state.missionsDone.includes(m.id)&&m.check()){state.missionsDone.push(m.id);state.cash+=m.reward;state.transactions.unshift({day:state.day,text:`Görev ödülü: ${m.title}`,amount:m.reward});notify(`Görev tamamlandı! <b>${fmt(m.reward)}</b> ödül kazandın.`);save();render()}})}
function drawChart(){const canvas=document.getElementById('chart');if(!canvas||!canvas.offsetWidth)return;const dpr=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const values=state.history.length?state.history:[state.cash],min=Math.min(...values)*.94,max=Math.max(...values)*1.06,range=Math.max(max-min,1);ctx.clearRect(0,0,w,h);const pts=values.map((v,i)=>({x:8+i*(w-16)/Math.max(values.length-1,1),y:h-8-(v-min)/range*(h-22)}));ctx.strokeStyle='#ffffff12';ctx.lineWidth=1;for(let i=1;i<4;i++){ctx.beginPath();ctx.moveTo(0,h*i/4);ctx.lineTo(w,h*i/4);ctx.stroke()}const grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#c3ef7735');grad.addColorStop(1,'#c3ef7700');ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineTo(pts.at(-1).x,h);ctx.lineTo(pts[0].x,h);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#c3ef77';ctx.lineWidth=2;ctx.stroke();pts.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,2.5,0,Math.PI*2);ctx.fillStyle='#c3ef77';ctx.fill()})}

