22:<section class="view" id="view-bank"><div class="section-head" style="margin-top:0"><div><h2>Banka & finans</h2><p>Nakit akışını yönet, yatırımlarını doğru zamanda finanse et.</p></div></div><div class="metric-grid" id="bankMetrics"></div><div class="market-grid"><div class="card"><div class="card-head">İşletme kredisi <small>Günlük faiz: %0,35</small></div><div class="loan-card" style="margin-top:18px"><div><h3>İşini büyütmek için sermaye</h3><p>Kredi üst limiti, şirket değerinin ve geri ödeme gücünün %60'ı kadardır.</p></div><button class="btn" id="loanBtn">Kredi başvurusu</button></div><div id="loanInfo" style="margin-top:15px"></div><div style="display:flex;gap:8px;margin-top:16px"><button class="btn secondary" onclick="window.deposit()">↓ Bankaya yatır · ₺10.000</button><button class="btn secondary" onclick="window.withdraw()">↑ Nakit çek · ₺10.000</button></div></div><div class="card"><div class="card-head">Finansal kayıtlar <small>Son işlemler</small></div><div id="transactions"></div></div></div><div class="section-head"><div><h2>Genişleme arazileri</h2><p>Şehirde doğru konum, güçlü büyümenin ilk adımı.</p></div></div><div class="biz-grid" id="landGrid"></div></section>
64:function buyCompany(id){const t=TYPES.find(x=>x.id===id);if(!t||owned(id))return;const cost=Math.round(t.cost*(state.land===1?1:1+(state.land-1)*.06));if(state.cash<cost){notify(`Միջոցները բավարար չեն. Պետք է ${fmt(cost)}։`,true);return}state.cash-=cost;state.companies.push({...t,value:t.value,level:1,days:0});state.transactions.unshift({day:state.day,text:`${t.name} kuruldu`,amount:-cost});state.rep+=10;save();render();notify(`<b>${t.name}</b> şehrin ekonomisine katıldı!`);if(state.companies.length===1)finishTutorialStep(1)}
66:function advanceDay(){state.day++;let t=totals(),mult=state.event===2?1.12:1;let income=0,expense=0;state.companies.forEach(c=>{const competition=state.competitors.some(r=>r.sector.includes(c.id==='tech'?'Teknoloji':c.id==='farm'?'Tarım':'') )?.94:1;const sales=Math.round(c.daily*mult*competition*(.93+Math.random()*.16));const costs=Math.round(c.expense*(state.event===2?1.2:state.event===1?.96:1));income+=sales;expense+=costs;c.days++;const prod=PRODUCTS.find(p=>p.name===c.product);if(prod){const quantity=Math.max(1,Math.floor(c.capacity*(.8+Math.random()*.3)));const marketQty=Math.min(quantity,Math.max(0,prod.stock+5));if(marketQty){const added=marketQty*prod.price;income+=Math.round(added*.08);prod.stock=Math.max(2,prod.stock-marketQty*.12)}}});const taxes=Math.round(income*.05);expense+=taxes;let interest=Math.round(state.debt*.0035);expense+=interest;state.cash+=income-expense;state.bank=Math.round(state.bank*1.0003);state.history.push(state.cash);state.history=state.history.slice(-7);state.competitors.forEach(c=>{c.value=Math.round(c.value*(.985+Math.random()*.035))});updateMarket();state.event=Math.floor(Math.random()*EVENTS.length);const ev=EVENTS[state.event];state.eventLog.unshift({day:state.day,...ev});state.eventLog=state.eventLog.slice(0,5);state.transactions.unshift({day:state.day,text:'Günlük faaliyet ve vergiler',amount:income-expense});state.transactions=state.transactions.slice(0,12);const month=['İlkbahar','Yaz','Sonbahar','Kış'][Math.floor((state.day-1)/30)%4];if(state.day%30===0)state.season++;save();render();notify(`Gün ${state.day}: net ${income-expense>=0?'kazanç':'zarar'} <b>${fmt(income-expense)}</b>`);checkAchievements();checkMissions()}
88:function renderBank(){const t=totals();document.getElementById('bankMetrics').innerHTML=metric('Nakit',fmt(state.cash),'Günlük kullanılabilir','₺')+metric('Banka bakiyesi',fmt(state.bank),'Günlük %0,03 getiri','▤')+metric('Kredi borcu',fmt(state.debt),state.debt?`Faiz: ${fmt(state.debt*.0035)} / gün`:'Aktif kredi yok','↘',state.debt>0)+metric('Şirket değeri',fmt(state.companies.reduce((a,c)=>a+c.value,0)),`${state.companies.length} aktif girişim`,'◈');document.getElementById('loanInfo').innerHTML=state.debt?`<div class="mission"><div>Güncel kredi borcu<strong style="display:block;color:var(--red);margin-top:5px">${fmt(state.debt)}</strong><small>Günlük faiz: ${fmt(state.debt*.0035)}</small></div><button class="btn secondary" onclick="window.repay()">Borç öde</button></div>`:'<div style="font-size:10px;color:var(--muted)">Kredi kullanımı isteğe bağlıdır. Günlük faiz, gün sonlarında borca eklenir.</div>';document.getElementById('transactions').innerHTML=state.transactions.length?state.transactions.slice(0,7).map(x=>`<div class="price-row" style="padding:10px 0;border-bottom:1px solid var(--line)"><span>Gün ${x.day}<small>${x.text}</small></span><b class="${x.amount>=0?'positive':'negative'}">${x.amount>=0?'+':''}${fmt(x.amount)}</b></div>`).join(''):'<div class="empty">Henüz finansal işlem yok.</div>';document.getElementById('landGrid').innerHTML=LANDS.map(l=>`<article class="card biz-card"><div class="biz-top"><div class="biz-emblem">${l.icon}</div><span class="status ${l.id<=state.land?'':'locked'}">${l.id<=state.land?'Sahip olunan':'Genişleme'}</span></div><h3>${l.name}</h3><p>${l.area} · Depo kapasitesini 25 birim artırır.</p><div class="biz-stats"><span>Bedel<b>${l.cost?fmt(l.cost):'Başlangıç deposu'}</b></span><span>Durum<b>${l.id<=state.land?'Sende':'Satılık'}</b></span></div>${l.id>state.land?`<button class="btn" onclick="window.land(${l.id})" ${l.id!==state.land+1?'disabled':''}>Arazi al</button>`:''}</article>`).join('')}
